useEffect(()=>{if(!chatOpen){setChatKeyboardHeight(0);return;}const viewport=window.visualViewport;const update=()=>{if(viewport)setChatKeyboardHeight(Math.max(0,window.innerHeight-(viewport.height+viewport.offsetTop)));};update();viewport?.addEventListener("resize",update);viewport?.addEventListener("scroll",update);return()=>{viewport?.removeEventListener("resize",update);viewport?.removeEventListener("scroll",update);};},[chatOpen]);
useEffect(()=>{if(!chatOpen)return;const y=window.scrollY;const body=document.body;const previous={position:body.style.position,top:body.style.top,width:body.style.width,overflow:body.style.overflow};body.style.position="fixed";body.style.top=`-${y}px`;body.style.width="100%";body.style.overflow="hidden";return()=>{body.style.position=previous.position;body.style.top=previous.top;body.style.width=previous.width;body.style.overflow=previous.overflow;window.scrollTo(0,y);};},[chatOpen]);
