function locate(){setLocationMessage("");if(!navigator.geolocation){setLocationMessage("Location is unavailable. Enter a ZIP code instead.");return}navigator.geolocation.getCurrentPosition(({coords})=>{setZip("");setLocation("Your location ("+coords.latitude.toFixed(2)+", "+coords.longitude.toFixed(2)+")");setLocationMessage("Location access granted. Showing Los Angeles demo providers; live distance matching is not connected.")},()=>setLocationMessage("Location permission was not granted. Enter a ZIP code instead."),{timeout:8000})}
function applyZip(){const value=zip.trim();if(!/^\d{5}$/.test(value)){setLocationMessage("Enter a valid 5-digit ZIP code.");return}setZip(value);setLocation("ZIP "+value);setLocationMessage("Showing demo providers whose sample service area includes "+value+".") }
