const activeProviderReviews=activeProvider?reviews.filter(r=>r.provider===activeProvider.name):[]; const activeProviderAverage=activeProviderReviews.length?(activeProviderReviews.reduce((sum,r)=>sum+r.rating,0)/activeProviderReviews.length).toFixed(1):null;
function sendChatMessage(text?:string){const question=(text??chatInput).trim();if(!question)return;setChatMessages(old=>[...old,{role:"user",text:question}]);setChatInput("");const q=question.toLowerCase();let answer="I can help you explore services, understand how Up&comer works, or find your next local pro. What are you looking to get done?";if(q.includes("junk")||q.includes("couch")||q.includes("haul")||q.includes("remove"))answer="For that, start with Junk Removal. Browse the category tiles and compare emerging providers, their profiles, reviews, and sample starting prices. The listings are demo data right now.";else if(q.includes("move")||q.includes("moving"))answer="Moving help is in the Moving category. You can browse a provider profile to see their details and submit a sample booking request. The current providers and availability are demo examples.";else if(q.includes("lawn")||q.includes("yard")||q.includes("grass"))answer="Take a look at Lawn Care. You can open a provider profile, review their details, and explore the sample appointment calendar.";else if(q.includes("price")||q.includes("cost")||q.includes("afford"))answer="Up&comer is designed to help customers discover emerging providers offering fair, upfront prices. Prices currently shown in this prototype are sample prices, not live quotes.";else if(q.includes("background")||q.includes("verified")||q.includes("check")||q.includes("safe"))answer="Provider verification is an important part of the Up&comer concept. The current verification status is simulated for this prototype—no real background checks have been ordered or completed.";else if(q.includes("book")||q.includes("appointment"))answer="To try booking, choose a service category, select View profile on a provider card, choose a date and available time, then submit a sample booking request. Nothing is sent to a real provider yet.";else if(q.includes("how")||q.includes("what is")||q.includes("work"))answer="Up&comer helps customers discover and book emerging local service providers, while giving newer businesses a place to build their reputation through customer feedback. This is currently a working demo with sample data.";setChatMessages(old=>[...old,{role:"assistant",text:answer}]);}

